var t=[{title:`Jak odpor funguje`,text:`Jednoručka váží stejně v každém bodě, ale odpor gumy závisí na tom, jak moc je natažená, jak je silná a o jaký výrobek jde. Delší nebo silnější guma se nerovná pevné váze a barevné kódy se mezi výrobci liší. Bod pohybu, kde je odpor nejvyšší, se také může lišit od cviku s volnou zátěží.`},{title:`Možnosti cviků`,text:`Gumy dobře fungují pro přítahy, tlaky, upažování, Pallof pressy a stahování z řádně nainstalovaného ukotvení. Smyčková guma kolem kolen přidává lehký odpor u cviků pro kyčle. U některých pohybů můžete jako jednoduché ukotvení stát na gumě, pokud nemůže sklouznout a vymrštit se nahoru.`},{title:`Kontrola a bezpečné ukotvení`,text:`Před každým tréninkem zkontrolujte praskliny, ztenčená místa, trhliny, poškozené rukojeti a opotřebované spojky. Použijte ukotvení určené k tomuto účelu podle pokynů výrobce a ujistěte se, že se nemůže uvolnit. Gumu nepřepínejte, nenechte ji třít o ostré hrany a nedávejte obličej do dráhy, kterou by se vymrštila zpět. Sklouznutá guma může způsobit poranění očí a další újmu.`},{title:`Progrese a záznam`,text:`Přidávejte kontrolovaná opakování, přejděte na gumu s větším odporem nebo změňte postoj či vzdálenost od ukotvení, pokud zůstane nové nastavení bezpečné. Napětí se mění s délkou, proto si zapište gumu nebo nastavení, které jste použili; její barva vám neřekne přesnou váhu v kilogramech. Nezvyšujte napětí gumy a rozsah prudce zároveň.`},{title:`Použití v TrainUp`,text:`V Profilu zadejte odpor gum, které máte. Gumy počítejte za dostupné jen tehdy, když máte bezpečné ukotvení pro cvik, který plánujete. Pokud nedokážete potvrdit ukotvení, stav gumy ani svůj prostor, zvolte bezpečnější alternativu.`}];var n=[{label:`NHS: bezpečnost odporových gum`,url:`https://abuhb.nhs.wales/files/patient-information-leaflets1/physiotherapy/safety-advice-when-exercising-with-resistance-bands-or-tubing-piu1332/`},{label:`Knihovna cviků ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Stanovisko ACSM z roku 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:t,sources:n};export{a as default,t as sections,n as sources};